@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<div class="container">
    <h1 class="mb-4">🔍 Track a Shipment</h1>

    <div class="input-group mb-4" style="max-width: 500px;">
        <input type="text" class="form-control" placeholder="Enter tracking number" @bind="searchNumber" @bind:event="oninput"
               @onkeydown="HandleKeyDown" />
        <button class="btn btn-primary" @onclick="Search">Search</button>
    </div>

    @if (loading)
    {
        <p><em>Searching...</em></p>
    }
    else if (result is not null)
    {
        @if (result.Found && result.Shipment is not null)
        {
            var s = result.Shipment;
            <div class="card" style="max-width: 600px;">
                <div class="card-header">
                    <strong>Tracking #@s.TrackingNumber</strong>
                    <span class="badge @GetStatusBadge(s.Status) float-end">@s.Status</span>
                </div>
                <div class="card-body">
                    <table class="table table-borderless mb-0">
                        <tbody>
                            <tr><th>From</th><td>@s.Origin</td></tr>
                            <tr><th>To</th><td>@s.Destination</td></tr>
                            <tr><th>Sender</th><td>@s.SenderName</td></tr>
                            <tr><th>Recipient</th><td>@s.RecipientName</td></tr>
                            <tr><th>Shipped</th><td>@s.ShippedDate.ToString("MMM dd, yyyy")</td></tr>
                            <tr><th>Est. Delivery</th><td>@(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "N/A")</td></tr>
                            @if (s.ActualDelivery.HasValue)
                            {
                                <tr><th>Delivered</th><td>@s.ActualDelivery.Value.ToString("MMM dd, yyyy")</td></tr>
                            }
                        </tbody>
                    </table>
                </div>
            </div>
        }
        else
        {
            <div class="alert alert-warning" style="max-width: 500px;">
                @(result.ErrorMessage ?? "Shipment not found.")
            </div>
        }
    }
</div>

@code {
    [Parameter] public string? TrackingNumber { get; set; }

    private string searchNumber = string.Empty;
    private TrackingResult? result;
    private bool loading;

    protected override async Task OnParametersSetAsync()
    {
        if (!string.IsNullOrWhiteSpace(TrackingNumber))
        {
            searchNumber = TrackingNumber;
            await Search();
        }
    }

    private async Task Search()
    {
        if (string.IsNullOrWhiteSpace(searchNumber)) return;
        loading = true;
        result = null;
        StateHasChanged();
        result = await ShipmentService.TrackShipmentAsync(searchNumber.Trim());
        loading = false;
    }

    private void HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            InvokeAsync(Search);
    }

    private static string GetStatusBadge(string status) => status switch
    {
        "Delivered" => "bg-success",
        "In Transit" => "bg-warning text-dark",
        "Pending" => "bg-secondary",
        "Cancelled" => "bg-danger",
        _ => "bg-info"
    };
}

