+    protected override async Task OnParametersSetAsync()
+    {
+        if (!string.IsNullOrWhiteSpace(TrackingNumber))
+        {
+            searchNumber = TrackingNumber;
+            await Search();
+        }
+    }
+
+    private async Task Search()
+    {
+        if (string.IsNullOrWhiteSpace(searchNumber)) return;
+        loading = true;
+        result = null;
+        StateHasChanged();
+        result = await ShipmentService.TrackShipmentAsync(searchNumber.Trim());
+        loading = false;
+    }
+
+    private void HandleKeyDown(KeyboardEventArgs e)
+    {
+        if (e.Key == "Enter")
+            InvokeAsync(Search);
+    }
+
+    private static string GetStatusBadge(string status) => status switch
+    {
+        "Delivered" => "bg-success",
+        "In Transit" => "bg-warning text-dark",
+        "Pending" => "bg-secondary",
+        "Cancelled" => "bg-danger",
+        _ => "bg-info"
+    };
+}
