+@page "/dispatch"
+@using Microsoft.AspNetCore.Authorization
+@using ShipmentTracker.Client.Models
+@using ShipmentTracker.Client.Services
+@attribute [Authorize(Roles = "Dispatcher")]
+@inject IShipmentService ShipmentService
+
+<PageTitle>Dispatch Management</PageTitle>
+
+<div class="container">
+    <h1 class="mb-4">🚚 Dispatch Management</h1>
+
+    @if (shipments is null)
+    {
+        <p><em>Loading shipments...</em></p>
+    }
+    else if (shipments.Count == 0)
+    {
+        <div class="alert alert-info">No shipments found.</div>
+    }
+    else
+    {
+        @if (!string.IsNullOrEmpty(statusMessage))
+        {
+            <div class="alert @(statusSuccess ? "alert-success" : "alert-danger") alert-dismissible fade show">
+                @statusMessage
+                <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
+            </div>
+        }
+
+        <div class="table-responsive">
+            <table class="table table-striped table-hover">
+                <thead class="table-dark">
+                    <tr>
+                        <th>Tracking #</th>
+                        <th>Origin</th>
+                        <th>Destination</th>
+                        <th>Recipient</th>
+                        <th>Shipped</th>
+                        <th>Status</th>
+                        <th>Action</th>
+                    </tr>
+                </thead>
+                <tbody>
+                    @foreach (var s in shipments)
+                    {
+                        <tr>
+                            <td>@s.TrackingNumber</td>
+                            <td>@s.Origin</td>
+                            <td>@s.Destination</td>
+                            <td>@s.RecipientName</td>
+                            <td>@s.ShippedDate.ToString("MMM dd, yyyy")</td>
+                            <td><span class="badge @GetStatusBadge(s.Status)">@s.Status</span></td>
+                            <td>
+                                <div class="input-group input-group-sm" style="max-width: 250px;">
+                                    <select class="form-select form-select-sm" @bind="selectedStatuses[s.Id]">
+                                        <option value="">-- Change --</option>
+                                        <option value="Pending">Pending</option>
+                                        <option value="In Transit">In Transit</option>
+                                        <option value="Delivered">Delivered</option>
+                                        <option value="Cancelled">Cancelled</option>
+                                    </select>
+                                    <button class="btn btn-sm btn-outline-primary"
+                                            disabled="@string.IsNullOrEmpty(GetSelectedStatus(s.Id))"
+                                            @onclick="() => UpdateStatus(s)">
+                                        Update
+                                    </button>
+                                </div>
+                            </td>
+                        </tr>
+                    }
+                </tbody>
+            </table>
+        </div>
+    }
+</div>
+
+@code {
+    private List<ShipmentDto>? shipments;
+    private Dictionary<int, string> selectedStatuses = new();
+    private string? statusMessage;
+    private bool statusSuccess;
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadShipments();
+    }
+
+    private async Task LoadShipments()
+    {
+        shipments = await ShipmentService.GetAllShipmentsAsync();
+        selectedStatuses = shipments.ToDictionary(s => s.Id, _ => string.Empty);
+    }
+
+    private string GetSelectedStatus(int id) =>
+        selectedStatuses.TryGetValue(id, out var val) ? val : string.Empty;
+
+    private async Task UpdateStatus(ShipmentDto shipment)
+    {
+        var newStatus = GetSelectedStatus(shipment.Id);
+        if (string.IsNullOrEmpty(newStatus)) return;
+
+        var success = await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
+        if (success)
+        {
+            statusMessage = $"Shipment {shipment.TrackingNumber} updated to '{newStatus}'.";
+            statusSuccess = true;
+            await LoadShipments();
+        }
+        else
+        {
+            statusMessage = $"Failed to update shipment {shipment.TrackingNumber}.";
+            statusSuccess = false;
+        }
+    }
