                 <button class="btn btn-primary" @onclick="GoToTrack">Track</button>
             </div>
         </div>
     </div>

     <div class="row">
         <div class="col-md-4 mb-3">
             <div class="card text-center">
                 <div class="card-body">
                     <h2 class="card-title text-primary">@totalShipments</h2>
                     <p class="card-text">Total Shipments</p>
                 </div>
             </div>
         </div>
         <div class="col-md-4 mb-3">
             <div class="card text-center">
                 <div class="card-body">
                     <h2 class="card-title text-warning">@inTransit</h2>
                     <p class="card-text">In Transit</p>
                 </div>
             </div>
         </div>
         <div class="col-md-4 mb-3">
             <div class="card text-center">
                 <div class="card-body">
                     <h2 class="card-title text-success">@delivered</h2>
                     <p class="card-text">Delivered</p>
                 </div>
             </div>
         </div>
     </div>
 </div>

 @code {
     private string trackingNumber = string.Empty;
     private int totalShipments;
     private int inTransit;
     private int delivered;

     protected override async Task OnInitializedAsync()
     {
         var shipments = await ShipmentService.GetAllShipmentsAsync();
         totalShipments = shipments.Count;
         inTransit = shipments.Count(s => s.Status == "In Transit");
         delivered = shipments.Count(s => s.Status == "Delivered");
     }

     private void GoToTrack()
     {
         if (!string.IsNullOrWhiteSpace(trackingNumber))
             Navigation.NavigateTo($"/track/{Uri.EscapeDataString(trackingNumber.Trim())}");
     }

     private void HandleKeyDown(KeyboardEventArgs e)
     {
         if (e.Key == "Enter")
             GoToTrack();
     }
 }
